fn test_the_producer_is_read_in_the_order_the_file_has_it() {
    let t: &mut crate::emon::transcriptctx::Tr = &mut crate::emon::transcriptctx::Tr::new();
    let a: &mut String = &mut crate::port::new_text();
    let b: &mut String = &mut crate::port::new_text();
    let c: &mut String = &mut crate::port::new_text();
    crate::testport::assert_eq(tr_read(t, &crate::testport::text_blob("{:emon-transcript 1 :producer {:engine \"tesseract\" :n 5 :version \"5.5.3\" :host \"a/b\"} :inputs [{:index 3 :length 99}] :entries []}")[..]), 0, "reads");
    crate::testport::assert_eq(tr_n_inputs(t), 1, "one input");
    crate::testport::assert_eq(tr_in_index(t, 0), 3, "its index");
    crate::testport::assert_eq(tr_in_length(t, 0), 99, "its length");
    crate::testport::assert_eq(tr_p_more(t, 0), 1, "a producer");
    tt_p_text(t, 0, a);
    crate::testport::assert_text(a, "engine=tesseract", "the first");
    let p1: i32 = tr_p_next(t, 0);
    tt_p_text(t, p1, b);
    crate::testport::assert_text(b, "version=5.5.3", "the second string");
    let p2: i32 = tr_p_next(t, p1);
    tt_p_text(t, p2, c);
    crate::testport::assert_text(c, "host=a/b", "the third");
    let p3: i32 = tr_p_next(t, p2);
    crate::testport::assert_eq(tr_p_more(t, p3), 0, "and no more");
}
