    tt_bad(0, &crate::testport::text_blob("{:emon-transcript :1 :inputs [] :entries []}")[..], tb_version(), "not an emon-transcript of version 1");
    tt_bad(0, &crate::testport::text_blob("{:emon-transcript 2 :emon-transcript 1 :inputs [] :entries []}")[..], tb_version(), "not an emon-transcript of version 1");
