pub(crate) fn tt_found_at(t: &mut crate::emon::transcriptctx::Tr, k: &mut crate::port::Cells, at: i32, cnt: i32) -> i32 {
    // The place of the entry a request finds, or -1.
    let e: i32 = tr_find(t, k, at, cnt);
    if e < 0 {
        return -1;
    }
    return tr_e_n(t, e);
}
pub(crate) fn tt_found(t: &mut crate::emon::transcriptctx::Tr, k: &mut crate::port::Cells) -> i32 {
    return tt_found_at(t, k, 0, 4);
}
pub(crate) fn tt_taken(t: &mut crate::emon::transcriptctx::Tr, k: &mut crate::port::Cells) -> i32 {
    // The place of the entry a request takes (and marks used), or -1.
    let e: i32 = tr_take(t, k, 0, 4);
    if e < 0 {
        return -1;
    }
    return tr_e_n(t, e);
}
pub(crate) fn tt_pair(mut c: &mut crate::port::Cells, index: i32, length: i32) -> i32 {
    crate::port::cells_push(c, index);
    crate::port::cells_push(c, length);
    return 0;
}
