#[test]
fn test_a_request_is_found_by_the_whole_record() {
    let t: &mut crate::emon::transcriptctx::Tr = &mut crate::emon::transcriptctx::Tr::new();
    let k: &mut crate::port::Cells = &mut crate::port::Cells::new();
    tt_entry(t, 0, tk_render(), 1, 10, 0);
    tt_entry(t, 0, tk_ocr(), 2, 20, 0);
    tt_entry(t, 1, tk_render(), 3, 30, 0);
    crate::testport::assert_eq(tr_index(t), 0, "indexed");
    tt_key(k, tk_ocr(), 2, 20);
    crate::testport::assert_eq(tt_found(t, k), 1, "the second entry is found by its place");
    tt_key(k, tk_render(), 3, 30);
    crate::testport::assert_eq(tt_found(t, k), 2, "the third");
    tt_key(k, tk_render(), 3, 31);
    crate::testport::assert_eq(tr_find(t, k, 0, 4), -1, "one cell different is a miss");
    tt_key(k, tk_decode(), 3, 30);
    crate::testport::assert_eq(tr_find(t, k, 0, 4), -1, "another kind is a miss");
    tt_key(k, tk_render(), 4, 30);
    crate::testport::assert_eq(tr_find(t, k, 0, 4), -1, "another id is a miss");
    tt_key(k, tk_render(), 3, 30);
    crate::testport::assert_eq(tr_find(t, k, 0, 3), -1, "a shorter record is a miss");
    crate::port::cells_push(k, 9);
    crate::testport::assert_eq(tr_find(t, k, 0, 5), -1, "a longer record is a miss");
}
