#[test]
fn test_the_entries_nobody_asked_for_are_counted() {
    let t: &mut crate::emon::transcriptctx::Tr = &mut crate::emon::transcriptctx::Tr::new();
    let k: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let out: &mut String = &mut crate::port::new_text();
    tt_entry(t, 0, tk_render(), 1, 10, 0);
    tt_entry(t, 0, tk_render(), 2, 20, 0);
    tt_entry(t, 0, tk_render(), 3, 30, 0);
    tr_index(t);
    crate::testport::assert_eq(tr_unused(t), 3, "all three");
    tt_key(k, tk_render(), 2, 20);
    crate::testport::assert_that(tr_take(t, k, 0, 4) >= 0, "one asked");
    crate::testport::assert_eq(tr_unused(t), 2, "two left");
    tr_take(t, k, 0, 4);
    crate::testport::assert_eq(tr_unused(t), 2, "asking twice counts once");
    tt_key(k, tk_render(), 2, 21);
    crate::testport::assert_eq(tr_take(t, k, 0, 4), -1, "a miss marks nothing");
    crate::testport::assert_eq(tr_unused(t), 2, "still two");
    tr_unused_msg(t, out);
    crate::testport::assert_text(out, "2 recorded entries were never asked for", "the sentence of transcript-bad");
}
#[test]
fn test_find_does_not_mark_and_take_does() {
    let t: &mut crate::emon::transcriptctx::Tr = &mut crate::emon::transcriptctx::Tr::new();
    let k: &mut crate::port::Cells = &mut crate::port::Cells::new();
    tt_entry(t, 0, tk_render(), 1, 10, 0);
    tr_index(t);
    tt_key(k, tk_render(), 1, 10);
    crate::testport::assert_that(tr_find(t, k, 0, 4) >= 0, "found");
    crate::testport::assert_eq(tr_unused(t), 1, "find leaves it");
    crate::testport::assert_that(tr_take(t, k, 0, 4) >= 0, "taken");
    crate::testport::assert_eq(tr_unused(t), 0, "take marks it");
}
